  else if(s.intent==='buying_intent'||s.intent==='question')action='manual_review';
  else if(s.intent==='objection'||s.intent==='complaint')action='content_idea';
  else action='monitor';
  if(ALLOWED.indexOf(action)<0||FORBIDDEN.indexOf(action)>=0)action='manual_review'; // never outreach
  // public contact handling
  let public_phone='', public_username='', public_profile_url='', public_contact_type='', contact_source_url='', contact_evidence_text='', contact_conf=0;
  const privacy=[]; let policy=str(cfg.contact_use_policy_default)||'aggregate_only';
  const evidenceAnchor=str(c.comment_url)||str(c.post_url)||str(c.source_url);
