      if(cp.conf<50){policy=str(cfg.contact_use_policy_weak_evidence)||'do_not_use';privacy.push('weak_contact_evidence');}
      else {policy=str(cfg.contact_use_policy_with_public_contact)||'manual_review';}
      privacy.push('public_contact_present_manual_review_only');
    } else {
