  if(!(str(c.author_name)||str(c.author_id)))privacy.push('no_public_identity');
  const painLabel=s.pains.join(', ')||'unknown';
  const reasons='intent='+s.intent+'('+Math.round(s.intent01*W.intent)+'); urgency='+Math.round(s.urgency01*W.urgency)+'; pain['+painLabel+']='+Math.round(s.pain01*W.pain)+'; niche='+Math.round(s.niche01*W.niche)+'; contact='+Math.round(s.contact01*W.contact)+'; region='+Math.round(s.region01*W.region)+'; fresh='+Math.round(s.fresh01*W.freshness);
  const svc=svcType(low(c.text));
  // Defect B fix: deterministic evidence wins; a non-informative upstream hint ('unknown'/empty) must NOT shadow it.
  const _hint=low(c.service_need); const _hintOk=_hint&&_hint!=='unknown'&&_hint!=='none'&&_hint!=='unclear'&&_hint!=='n/a';
  const service_type_resolved=(svc!=='unknown')?svc:(_hintOk?str(c.service_need):'unknown');
