// Defect E: precise zero-write diagnosis (distinguish dedup / no-source / none-relevant / below-threshold / supplier / cap).
function diagnoseZeroWrite(){
  if(out.length>0)return {reason:'not_applicable',next:''};
  if((raw.length+review.length)===0)
    return {reason:'no_source_rows', next:'No source rows were read. Run a source connector first (WF13 VK fixture/live, WF09, WF11) to populate raw_market_records, then re-run WF14.'};
  if(cands.length===0)
    return {reason:'no_audience_rows', next:'Source rows exist but none are audience/consumer rows (all competitor/market/non-audience). Collect consumer comments/questions before expecting leads.'};
  if(scored.length===0 && dupSkipped>0 && dupSkipped>=irrelevant && dupSkipped>=supplierSkipped && dupSkipped>=belowThreshold)
    return {reason:'all_eligible_already_exist', next:'No new rows written because all '+dupSkipped+' eligible signal(s) already exist in public_lead_signals (deduplicated). Deduplication succeeded — no threshold change needed. Collect NEW source data (run WF13 again on new posts/comments) before expecting new leads.'};
  if(scored.length===0 && belowThreshold>0 && belowThreshold>=irrelevant && belowThreshold>=supplierSkipped)
    return {reason:'below_threshold', next:belowThreshold+' relevant candidate(s) scored below min_lead_score='+minScore+'. Lower min_lead_score only if weaker leads are acceptable; otherwise collect stronger-intent sources.'};
  if(scored.length===0 && supplierSkipped>0 && supplierSkipped>=irrelevant)
    return {reason:'supplier_excluded', next:supplierSkipped+' candidate(s) were supplier/competitor adverts (excluded by policy), not consumer demand. Expected; collect audience comments under competitor posts.'};
  if(scored.length===0 && irrelevant>0)
    return {reason:'none_relevant', next:irrelevant+' candidate(s) showed no consumer-demand evidence (irrelevant). Widen sources or the time window; no threshold change needed.'};
  if(afterFilters>maxWrite)
    return {reason:'append_cap', next:'Eligible signals exceeded the append cap (max_signals_to_write='+maxWrite+'); raise the cap or narrow the window.'};
  return {reason:'no_new_signals', next:'No new public lead signals; run source connectors (WF13 VK / WF09 / WF11) first, widen time_window_days, or lower min_lead_score.'};
}
